const input = $input.first()?.json || {};

function extractFolderId(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';

  // Common forms:
  // https://drive.google.com/drive/folders/<ID>
  // https://drive.google.com/open?id=<ID>
  // Plain folder ID
  const foldersMatch = raw.match(/\/folders\/([a-zA-Z0-9_-]+)/);
  if (foldersMatch) return foldersMatch[1];

  const idMatch = raw.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  if (idMatch) return idMatch[1];

  const parts = raw.split('/').filter(Boolean);
  const maybeId = parts.find(part => /^[a-zA-Z0-9_-]{20,}$/.test(part));
  return maybeId || raw;
}

function cleanDni(value) {
  return String(value || '').replace(/\s+/g, '').toUpperCase();
}

const folderId = extractFolderId(input.folder_link || input.folder_id);
const codes = ['C003','C004','C005','C006','C007','C008','D003','D004','D005','D006','D007','D008'];
const qCodes = codes.map(code => `name contains '${code}'`).join(' or ');

if (!folderId) {
  return [{
    json: {
      ...input,
      folder_id: '',
      drive_q: '',
      has_folder: false,
      error: 'No folder ID could be extracted from folder_link'
    }
  }];
}

return [{
  json: {
    ...input,
    folder_id: folderId,
    dni_t1_clean: cleanDni(input.dni_t1),
    dni_t2_clean: cleanDni(input.dni_t2),
    has_second_holder: Boolean(input.nombre_t2) && String(input.nombre_t2).trim().toUpperCase() !== 'NO TIENE',
    has_folder: true,
    drive_q: `'${folderId}' in parents and trashed=false and (${qCodes})`
  }
}];

const meta = $('Prepare Drive Query').first().json;
const files = $input.first()?.json?.files || [];

const map = {
  C003: { field: 'Adjuntar DNI', holder: 't1', decrypt: false },
  C004: { field: 'Vida laboral', holder: 't1', decrypt: false },
  C005: { field: '3 últimas nóminas', holder: 't1', decrypt: true },
  C006: { field: 'Contrato de trabajo', holder: 't1', decrypt: false },
  C007: { field: 'IRPF o Certificado de Retenciones', holder: 't1', decrypt: false },
  C008: { field: 'Movimientos de cuenta', holder: 't1', decrypt: true },

  D003: { field: 'Adjuntar DNI - Segundo Titular', holder: 't2', decrypt: false },
  D004: { field: 'Vida Laboral - Segundo Titular', holder: 't2', decrypt: false },
  D005: { field: '3 últimas nóminas - Segundo Titular', holder: 't2', decrypt: true },
  D006: { field: 'Contrato de trabajo - Segundo Titular', holder: 't2', decrypt: false },
  D007: { field: 'IRPF o Certificado de Retenciones - Segundo Titular', holder: 't2', decrypt: false },
  D008: { field: 'Movimientos de cuenta - Segundo Titular', holder: 't2', decrypt: true },
};

const order = Object.keys(map);

const items = [];

for (const file of files) {
  const name = file.name || '';
  const code = order.find(c => name.includes(c));
  if (!code) continue;

  const config = map[code];

  // Archivos vacíos (0 bytes) en la carpeta: PDF.co no puede leerlos y hacen fallar el merge completo
  // ("Input file is damaged…") o el desencriptado (timeout). Se ignoran; el resto del dossier sigue igual.
  if (file.size !== undefined && file.size !== null && Number(file.size) === 0) continue;

  if (config.holder === 't2' && !meta.has_second_holder) {
    continue;
  }

  const isPdf = file.mimeType === 'application/pdf' || /\.pdf$/i.test(name);
  const password = config.holder === 't2' ? meta.dni_t2_clean : meta.dni_t1_clean;
  const needsDecrypt = Boolean(config.decrypt && isPdf && password);

  items.push({
    json: {
      id: file.id,
      name,
      filename: name,
      mimeType: file.mimeType,
      size: file.size ? Number(file.size) : null,
      code,
      field: config.field,
      holder: config.holder,
      needsDecrypt,
      password,
      order: order.indexOf(code),
      webViewLink: file.webViewLink,
      webContentLink: file.webContentLink,
      source: 'drive_fallback'
    }
  });
}

items.sort((a, b) => {
  const ao = a.json.order ?? 999;
  const bo = b.json.order ?? 999;
  if (ao !== bo) return ao - bo;
  return String(a.json.name).localeCompare(String(b.json.name), 'es');
});

if (items.length === 0) {
  return [{
    json: {
      _empty: true,
      source: 'drive_fallback',
      deal_id: meta.deal_id,
      nombre_t2: meta.nombre_t2,
      message: 'No matching C/D dossier documents found in Drive folder'
    }
  }];
}

return items;

const originalItems = $('Explode Drive Files').all().map(item => item.json);
const currentItems = $input.all();

return currentItems.map((item, index) => {
  const original = originalItems[index] || item.json || {};
  const publicUrl = `https://drive.google.com/uc?export=download&id=${original.id}`;

  return {
    json: {
      ...original,
      url: publicUrl,
      publicUrl,
      share_error: item.json?.error?.message || null
    }
  };
});

const originals = $('Prepare File URLs').all().map((item, index) => ({
  ...(item.json || {}),
  _originalIndex: index,
}));

const requests = $('Prepare Drive Decrypt Requests')
  .all()
  .map(item => item.json || {})
  .filter(item => !item._no_decrypt_requests);

const responses = $input.all().map(item => item.json || {});

function readMessage(response) {
  return String(
    response.message ||
    response.error?.message ||
    response.error ||
    response.body?.message ||
    response.body?.error ||
    'PDF.co security/remove did not return a decrypted URL'
  );
}

function isBenignNotEncrypted(message) {
  return /not\s+(encrypted|protected|secured)|not\s+password\s+protected|no\s+password|password\s+(is\s+)?not\s+required|does\s+not\s+require\s+a\s+password|document\s+is\s+not\s+encrypted/i.test(message);
}

const byOriginalIndex = new Map();

responses.forEach((response, responseIndex) => {
  const request = requests[responseIndex] || {};
  if (request._originalIndex === undefined) return;

  const ok = response.error === false && Boolean(response.url);
  const message = readMessage(response);
  const benignNotEncrypted = !ok && isBenignNotEncrypted(message);

  byOriginalIndex.set(request._originalIndex, {
    ok,
    url: response.url || null,
    message,
    benignNotEncrypted,
  });
});

return originals.map(original => {
  const result = byOriginalIndex.get(original._originalIndex);

  // Files that never needed decrypt keep their original public URL.
  if (!original.needsDecrypt) {
    return {
      json: {
        ...original,
        original_url: original.publicUrl || original.url,
        url: original.publicUrl || original.url,
        decrypted: false,
        decrypt_failed: false,
        excluded_from_merge: false,
        decrypt_error: null,
      }
    };
  }

  // PDF.co succeeded: use the unlocked URL.
  if (result?.ok && result.url) {
    return {
      json: {
        ...original,
        original_url: original.publicUrl || original.url,
        url: result.url,
        decrypted: true,
        decrypt_failed: false,
        excluded_from_merge: false,
        decrypt_error: null,
      }
    };
  }

  // PDF was not actually encrypted: keep the original URL.
  if (result?.benignNotEncrypted) {
    return {
      json: {
        ...original,
        original_url: original.publicUrl || original.url,
        url: original.publicUrl || original.url,
        decrypted: false,
        decrypt_failed: false,
        excluded_from_merge: false,
        decrypt_error: null,
      }
    };
  }

  // PDF.co could not unlock it with the available DNI: exclude it from the merge.
  return {
    json: {
      ...original,
      original_url: original.publicUrl || original.url,
      url: null,
      decrypted: false,
      decrypt_failed: true,
      excluded_from_merge: true,
      decrypt_error: result?.message || 'PDF.co could not decrypt this file with the available DNI',
    }
  };
});

const meta = $('Prepare Drive Query').first().json;
const inputItems = $input.all().map(item => item.json || {});
const docs = inputItems.filter(item => !item._empty && item.url);
const failedDecryptDocs = inputItems.filter(item => item.decrypt_failed && item.excluded_from_merge);

const fields = [
  'Adjuntar DNI',
  'Vida laboral',
  '3 últimas nóminas',
  'Contrato de trabajo',
  'IRPF o Certificado de Retenciones',
  'Movimientos de cuenta',
  'Adjuntar DNI - Segundo Titular',
  'Vida Laboral - Segundo Titular',
  '3 últimas nóminas - Segundo Titular',
  'Contrato de trabajo - Segundo Titular',
  'IRPF o Certificado de Retenciones - Segundo Titular',
  'Movimientos de cuenta - Segundo Titular'
];

const record = {
  id: `drive_fallback_${meta.deal_id || Date.now()}`,
  __source: 'drive_fallback',
  deal_id: meta.deal_id,
  folder_id: meta.folder_id,
  nombre_t2: meta.nombre_t2,
  numero_expediente: meta.numero_expediente,
  person_name_t1: meta.person_name_t1,
  row_num: meta.row_num || '',
  Asesor: meta.Asesor || meta.asesor || '',
  docs_found_count: docs.length,
  docs_excluded_count: failedDecryptDocs.length,
  decrypted_count: docs.filter(d => d.decrypted).length,
  decrypt_failed_count: failedDecryptDocs.length,
  excluded_documents: failedDecryptDocs.map(d => ({
    field: d.field,
    code: d.code,
    holder: d.holder,
    filename: d.filename || d.name,
    original_url: d.original_url || d.publicUrl || d.url,
    decrypt_error: d.decrypt_error || null,
  })),
};

for (const field of fields) {
  record[field] = [];
}

for (const doc of docs) {
  if (!record[doc.field]) record[doc.field] = [];
  record[doc.field].push({
    url: doc.url,
    size: doc.size,
    filename: doc.filename || doc.name,
    id: doc.id,
    code: doc.code,
    source: 'drive_fallback',
    decrypted: Boolean(doc.decrypted),
    decrypt_failed: Boolean(doc.decrypt_failed),
    excluded_from_merge: false
  });
}

return [{ json: record }];

const meta = $('Prepare Drive Query').first().json;
const inputItems = $input.all().map(item => item.json || {});
const docs = inputItems.filter(item => !item._empty && item.url);
const failedDecryptDocs = inputItems.filter(item => item.decrypt_failed && item.excluded_from_merge);

const fields = [
  'Adjuntar DNI',
  'Vida laboral',
  '3 últimas nóminas',
  'Contrato de trabajo',
  'IRPF o Certificado de Retenciones',
  'Movimientos de cuenta',
