return [{ json: record }];

const originals = $('Prepare File URLs').all().map((item, index) => ({
  ...(item.json || {}),
  _originalIndex: index,
}));

const requests = originals.filter(item => item.needsDecrypt);

if (requests.length === 0) {
  return [{
    json: {
      _no_decrypt_requests: true,
      total_files: originals.length,
      message: 'No Drive files require PDF.co decrypt'
    }
  }];
}

return requests.map(item => ({ json: item }));

const originals = $('Prepare File URLs').all().map((item, index) => ({
  ...(item.json || {}),
  _originalIndex: index,
}));

return originals.map(original => ({
  json: {
    ...original,
    original_url: original.publicUrl || original.url,
    url: original.publicUrl || original.url,
    decrypted: false,
    decrypt_failed: false,
    excluded_from_merge: false,
    decrypt_error: null,
  }
}));

const meta = $('Prepare Drive Query').first().json || {};
const items = $input.all().map(item => item.json || {});
const failures = items.filter(item => item.decrypt_failed && item.excluded_from_merge);

if (failures.length === 0) {
  return [];
}

const list = failures.map((doc, index) => {
  const holder = doc.holder === 't2' ? 'Segundo titular' : 'Primer titular';
  const name = doc.filename || doc.name || doc.id || 'archivo sin nombre';
  const field = doc.field || doc.code || 'documento';
  const error = doc.decrypt_error ? ` Error: ${doc.decrypt_error}` : '';
  return `${index + 1}. ${holder} — ${field} — ${name}.${error}`;
}).join('\n');

return [{
  json: {
    person_name_t1: meta.person_name_t1 || '',
    Asesor: meta.Asesor || meta.asesor || '',
    deal_id: meta.deal_id || '',
    row_num: meta.row_num || '',
    "Error msg": `<@U08USF1LZSP> <@U0A6ZSLGC1Y> ⚠️ Algunos documentos del fallback de Google Drive no se pudieron desencriptar con el DNI disponible y fueron excluidos del merge para que el dossier no falle.\n\nDeal ID: ${meta.deal_id || 'N/A'}\nCliente: ${meta.person_name_t1 || 'N/A'}\nDocumentos excluidos: ${failures.length}\n\n${list}\n\nHay que agregarlos manualmente al dossier si corresponden.`
  }
}];

// Solo para los PDFs que PDF.co rechazó por contraseña incorrecta: se prueban variantes del mismo DNI/NIE
// (minúsculas, sin letra final, NIE sin letra inicial o con su número equivalente, solo dígitos).
const requests = $('Prepare Drive Decrypt Requests').all().map(i => i.json || {}).filter(r => !r._no_decrypt_requests);
const responses = $input.all().map(i => i.json || {});

function msg(r) {
  const raw = r.message || r.error?.message || r.error || '';
  return typeof raw === 'string' ? raw : JSON.stringify(raw);
}
const wrongPassword = (r) => !(r.error === false && r.url) && /password-protected|incorrect password|invalid password|wrong password|\b441\b/i.test(msg(r));

function variants(pwd) {
  const d = String(pwd || '').replace(/[\s.-]+/g, '').toUpperCase();
  if (!d) return [];
  const nie = { X: '0', Y: '1', Z: '2' };
  const list = [
    d.toLowerCase(),                                   // 12345678z
    d.slice(0, -1) + d.slice(-1).toLowerCase(),         // 12345678z / X1234567l
    d.replace(/[A-Z]$/, ''),                           // 12345678 / X1234567
    d.replace(/^[XYZ]/, ''),                           // 1234567L (NIE)
    d.replace(/^[XYZ]/, m => nie[m]),                  // 01234567L (NIE)
    d.replace(/\D/g, ''),                              // solo dígitos
  ];
  return [...new Set(list)].filter(v => v && v.length >= 5 && v !== d);
}

const out = [];
requests.forEach((request, idx) => {
  if (!wrongPassword(responses[idx] || {})) return;
  for (const p of variants(request.password)) out.push({ json: { ...request, password: p, _reqIndex: idx } });
});

return out.length ? out : [{ json: { _no_retries: true } }];

// Una respuesta por documento (mismo orden que 'Prepare Drive Decrypt Requests'):
// la del primer intento, o la de la variante de contraseña que haya funcionado.
const ok = r => r && r.error === false && Boolean(r.url);
const finalResponses = $('PDF.co Remove Security').all().map(i => i.json || {});

if ($('PDF.co Remove Security (variantes DNI)').isExecuted) {
  const tries = $('Contraseñas alternativas').all().map(i => i.json || {});
  const res = $('PDF.co Remove Security (variantes DNI)').all().map(i => i.json || {});
  tries.forEach((t, k) => {
    if (ok(res[k]) && !ok(finalResponses[t._reqIndex])) finalResponses[t._reqIndex] = { ...res[k], password_variant_used: true };
  });
}

return finalResponses.map(r => ({ json: r }));
